export type Question = {id:string; category:CategoryId; arena:number; stem:string; options:[string,string,string,string]; correct:number; feedback:string; basis:string};
const Q: Question[]=[];
function add(category: CategoryId, arena:number, stem:string, correct:string, b:string, c:string, d:string, feedback:string, basis:string){
 Q.push({id:`${category}-${arena}-${Q.filter(x=>x.category===category && x.arena===arena).length+1}`,category,arena,stem,options:[correct,b,c,d],correct:0,feedback,basis});
}
// Banco educativo ampliado en v14: 225 preguntas (50 en arena 0 y 35 en cada arena posterior, sumadas las 5 ramas).
// CIVIL · arena 0
add('civil',0,'Una compraventa inmobiliaria ordinaria válida no se inscribe todavía. En principio, ¿qué ocurre entre comprador y vendedor?','El comprador adquiere la propiedad conforme al artículo 949.','La venta es nula por falta de inscripción.','El comprador solo adquiere posesión.','La propiedad se transfiere al pagar impuestos.','La inscripción no suele ser constitutiva de la compraventa de inmueble determinado.','Código Civil, art. 949');
add('civil',0,'Una tía dona un departamento mediante documento privado con firmas legalizadas. ¿Qué falta para la validez?','La escritura pública exigida por ley.','Una declaración jurada del donatario.','La mera entrega de llaves.','Solo un recibo del impuesto predial.','La donación inmobiliaria requiere escritura pública bajo sanción de nulidad.','Código Civil, art. 1625');
add('civil',0,'Las partes firman una escritura de hipoteca, pero no se inscribe. ¿Qué afirmación es correcta?','La garantía hipotecaria aún no está válidamente constituida.','Basta la escritura para que exista hipoteca.','La hipoteca nace cuando se desembolsa el préstamo.','La inscripción solo sirve para publicidad.','La inscripción de la hipoteca es requisito de validez.','Código Civil, art. 1099');
add('civil',0,'Se vende un inmueble arrendado cuyo contrato de alquiler estaba inscrito. ¿Qué debe hacer el nuevo dueño?','Respetar el arrendamiento y sustituir al arrendador.','Expulsar al arrendatario de inmediato.','Exigir que el inquilino firme otro contrato.','Ignorar todas las obligaciones del contrato.','El arrendamiento inscrito es oponible al adquirente según la ley.','Código Civil, art. 1708');
add('civil',0,'¿Cuál es la diferencia esencial entre propiedad y posesión?','La propiedad es un derecho; la posesión se refiere al ejercicio de hecho de poderes sobre el bien.','Todo poseedor es necesariamente propietario.','Solo se posee lo que está inscrito.','La propiedad siempre exige tenencia material.','Puede poseerse sin ser propietario y ser propietario sin poseer materialmente.','Código Civil, derechos reales');
// CIVIL · arena 1
add('civil',1,'Un copropietario vende únicamente su cuota ideal en un inmueble. ¿Cuál es la idea central?','La cuota ideal es distinta de la totalidad física del inmueble.','Siempre vende el terreno completo.','La venta de cuota ideal es imposible.','Debe separarse materialmente el inmueble antes de todo acto.','La copropiedad se expresa en cuotas ideales de los titulares.','Código Civil, copropiedad');
add('civil',1,'Un arrendamiento no inscrito precede a la venta del bien. ¿Qué debe evaluarse según el artículo 1708?','Si el comprador asumió la obligación de respetarlo y las reglas legales aplicables.','Si el inquilino cambió las cerraduras.','Si la escritura de compra tiene más páginas.','Si el vendedor conservó copia de las llaves.','La inscripción y el eventual compromiso de respeto influyen en la oponibilidad.','Código Civil, art. 1708');
add('civil',1,'Se constituye una servidumbre de paso. ¿Qué idea la caracteriza?','Impone un gravamen sobre un predio en beneficio de otro según el supuesto legal.','Transfiere siempre la propiedad del predio sirviente.','Es equivalente al contrato de alquiler.','Confiere dominio exclusivo de ambos inmuebles.','La servidumbre es un derecho real con contenido específico sobre predios.','Código Civil, servidumbres');
add('civil',1,'Dos personas compran conjuntamente un inmueble sin dividirlo físicamente. ¿Qué puede originarse?','Copropiedad con cuotas ideales.','Propiedad exclusiva de cada habitación.','Dos títulos de propiedad sobre el total a favor de uno solo.','Extinción automática de los derechos reales.','La copropiedad permite pluralidad de titulares sin partición material.','Código Civil, copropiedad');
add('civil',1,'El vendedor incumple una obligación del contrato. ¿Se convierte automáticamente en delito?','No; el incumplimiento civil no basta por sí solo para configurar delito.','Sí, toda deuda impaga constituye estafa.','Sí, si el contrato no está inscrito.','Sí, por el solo perjuicio económico.','Las consecuencias civiles y penales tienen presupuestos distintos.','Código Civil y Código Penal');
// CIVIL · arena 2
add('civil',2,'Un comprador tiene contrato válido pero no inscribe; otro afirma un derecho posterior. ¿Qué debe analizarse?','Las reglas de concurrencia, publicidad y protección de terceros del caso concreto.','Solo el tamaño del inmueble.','Únicamente quién posee las llaves.','Exclusivamente quién pagó la alcabala antes.','En conflictos entre adquirentes no basta repetir que el contrato transmite propiedad.','Código Civil, arts. 949, 1135 y 2014');
add('civil',2,'Una persona posee un inmueble por años y solicita prescripción adquisitiva. ¿Qué conclusión es correcta?','La duración por sí sola no basta: deben verificarse requisitos legales de posesión.','Toda posesión de seis meses genera propiedad.','La posesión irregular siempre es suficiente.','Nunca es posible adquirir por prescripción.','Deben evaluarse continuidad, pacificidad, publicidad, concepto de propietario y plazo aplicable.','Código Civil, art. 950');
add('civil',2,'Se extingue la obligación garantizada con una hipoteca. ¿Qué debe distinguirse?','Extinción de la obligación y cancelación registral del gravamen.','Todo gravamen registrado es perpetuo.','El deudor pierde automáticamente la propiedad.','La extinción del crédito constituye una nueva venta.','La cancelación registral puede requerir actuación formal para reflejar la extinción.','Código Civil, hipoteca y extinción');
add('civil',2,'El usufructuario usa un inmueble ajeno. ¿Cuál es el límite conceptual?','No adquiere por ello el dominio del inmueble.','Puede vender necesariamente la propiedad ajena.','Se convierte siempre en copropietario.','El usufructo es idéntico a la hipoteca.','El usufructo permite disfrute en el marco del derecho constituido sin transferir propiedad.','Código Civil, usufructo');
add('civil',2,'Una persona firmó en representación de otra. ¿Qué resulta clave para la eficacia del acto?','Verificar facultades representativas suficientes para ese acto.','Que el representante sea mayor que el comprador.','Que el contrato tenga sello de cualquier empresa.','Que la firma se produzca necesariamente en un banco.','La representación requiere examinar su alcance y la actuación en nombre del representado.','Código Civil, representación');
// CIVIL · arena 3
add('civil',3,'Una parte aparenta vender un inmueble, pero ambas acuerdan que no quieren producir efecto alguno. ¿Qué figura debe evaluarse?','Simulación absoluta del acto jurídico.','Tradición material del inmueble.','Mora automática del comprador.','Usufructo constituido por tolerancia.','La discrepancia deliberada entre declaración aparente y voluntad común exige examinar simulación.','Código Civil, simulación');
add('civil',3,'Un contrato es anulable por un vicio de voluntad. ¿Cuál es la precisión conceptual?','No equivale sin más a la nulidad absoluta; su régimen y efectos son distintos.','Todo acto anulable es inexistente desde su firma.','La anulabilidad siempre se subsana con inscripción.','Toda nulidad y anulabilidad son sinónimos legales.','La ley distingue causales y régimen de nulidad y anulabilidad.','Código Civil, arts. 219 y 221');
add('civil',3,'En un proceso de reivindicación aparece una alegación de prescripción adquisitiva. ¿Qué debe analizarse?','La posible adquisición originaria de propiedad y sus requisitos frente a la pretensión reivindicatoria.','Solo la antigüedad del documento notarial.','La marca de cerradura instalada por el poseedor.','Únicamente el pago de recibos de luz.','La prescripción alegada exige prueba de sus propios presupuestos legales.','Código Civil, propiedad y prescripción');
add('civil',3,'Las partes pactan una condición suspensiva válida para la eficacia de un negocio. ¿Qué distingue esa condición?','La eficacia prevista depende del acontecimiento futuro e incierto pactado.','El contrato siempre queda automáticamente nulo.','La condición equivale al precio.','La condición vuelve innecesario todo consentimiento.','Una condición suspensiva actúa sobre la eficacia según lo pactado y las reglas legales.','Código Civil, modalidades del acto jurídico');
add('civil',3,'Dos copropietarios discrepan sobre dividir un bien común. ¿Qué institución corresponde revisar?','Partición de la copropiedad.','Inscripción constitutiva de hipoteca.','Donación universal presunta.','Falsedad ideológica penal automática.','La partición es una institución propia de la comunidad de bienes.','Código Civil, copropiedad y partición');
// CIVIL · arena 4
add('civil',4,'Un adquirente invoca fe pública registral aunque una causa de invalidez constaba en un título archivado. ¿Qué ocurre?','La protección del artículo 2014 no procede bajo esas condiciones.','Siempre prevalece su buena fe subjetiva.','La onerosidad elimina cualquier defecto archivado.','Solo importa haber recibido la posesión.','La información de títulos archivados sustentatorios integra el examen legal del tercero.','Código Civil, art. 2014');
add('civil',4,'Una escritura pública es formalmente correcta, pero el acto tiene objeto jurídicamente imposible. ¿Qué debe diferenciarse?','La forma documental de la validez sustantiva del negocio.','Una escritura siempre convalida cualquier contenido.','El notario puede eliminar por sí mismo una causal legal.','La inscripción convierte en posible todo objeto.','La forma pública no suprime vicios sustantivos de validez.','Código Civil, requisitos del acto jurídico');
add('civil',4,'Una hipoteca garantiza una obligación futura determinable. ¿Qué análisis es más adecuado?','Verificar la determinabilidad legal de la obligación y la válida constitución de la hipoteca.','Negarla siempre porque la obligación es futura.','Considerar que no requiere registro.','Confundirla con transferencia de propiedad.','Las obligaciones futuras pueden plantearse con requisitos de determinabilidad y publicidad.','Código Civil, hipoteca');
add('civil',4,'Un propietario constituye usufructo y posteriormente vende su inmueble. ¿Qué aspecto debe examinarse?','La subsistencia y oponibilidad del usufructo constituido conforme a derecho.','Que el usufructo se transforma siempre en hipoteca.','Que la venta hace inexistente cualquier derecho previo.','Que el usufructuario adquiere automáticamente dominio.','Los derechos reales preexistentes deben analizarse frente a la nueva titularidad.','Código Civil, derechos reales');
add('civil',4,'Una compraventa se discute por defecto de representación del vendedor. ¿Cuál es el análisis principal?','Alcance del poder, eficacia del acto y protección de terceros según corresponda.','Solo el valor declarado del impuesto.','La antigüedad del sello notarial como único dato.','Si el comprador tiene un contrato de telefonía.','Un defecto de representación exige separar validez, eficacia y consecuencias registrales.','Código Civil, representación');
// CIVIL · arena 5
add('civil',5,'A vende a B; B no inscribe; A figura titular y vende a C, que inscribe. ¿Qué enfoque evita una conclusión precipitada?','Examinar reglas de concurrencia, buena fe, títulos archivados y demás hechos probados.','Afirmar que siempre gana B sin excepciones.','Afirmar que siempre gana C solo por tener partida.','Dar preferencia al comprador que pagó más.','Los conflictos de doble venta exigen integrar normas civiles y registrales con los hechos.','Código Civil, arts. 949, 1135 y 2014');
add('civil',5,'Un negocio aparente encubre una liberalidad inmobiliaria sin escritura pública correspondiente. ¿Qué debe investigarse?','La verdadera naturaleza del negocio y los requisitos solemnes de la donación.','Solo el color del documento firmado.','Que cualquier apariencia basta para validar el fondo.','Que toda liberalidad está exenta de solemnidad.','La calificación del negocio subyacente puede activar formas exigidas bajo sanción de nulidad.','Código Civil, simulación y art. 1625');
add('civil',5,'Un acreedor invoca una garantía real sobre finca que su deudor dejó de poseer. ¿Qué enfoque es correcto?','Diferenciar titularidad, garantía inscrita, persecución y oponibilidad en el caso concreto.','Concluir que sin posesión del deudor no existe hipoteca.','Dar por inexistente la deuda.','Suponer que toda venta extingue el gravamen.','Los derechos reales de garantía se analizan separadamente de la tenencia material.','Código Civil, hipoteca');
add('civil',5,'El demandado reivindicatorio sostiene posesión como propietario, pero hay periodos interrumpidos. ¿Qué importa?','Determinar si se cumplen continuidad y demás requisitos de la prescripción invocada.','Sumar cualquier tiempo de ocupación sin condiciones.','Presumir propiedad por recibos de agua.','Excluir siempre el análisis posesorio.','La prescripción no se presume únicamente por ocupación y requiere examinar sus requisitos.','Código Civil, art. 950');
add('civil',5,'Un tercer adquirente invoca legitimación del asiento pese a nulidad discutida del acto causal. ¿Cuál es la distinción crítica?','Presunción registral, validez sustantiva y protección especial de terceros son planos distintos.','La legitimación sana cualquier nulidad.','Una denuncia elimina por sí sola el asiento.','Todo asiento nulo permite recuperar posesión sin trámite.','Los arts. 2013 y 2014 cumplen funciones distintas y no convalidan automáticamente títulos nulos.','Código Civil, arts. 2013 y 2014');

// REGISTRAL · arena 0
add('registral',0,'¿Qué entidad administra los Registros Públicos en el Perú?','SUNARP.','SUNAT.','RENIEC en todos los casos.','Indecopi.','SUNARP dirige el sistema registral; SUNAT y RENIEC cumplen funciones distintas.','Ley del Sistema Nacional de los Registros Públicos');
add('registral',0,'La partida registral muestra un propietario. ¿Qué principio presume la exactitud y validez del asiento vigente?','Legitimación registral.','Prescripción adquisitiva.','Autonomía de voluntad.','Reserva tributaria.','La legitimación permite actuar conforme a los asientos mientras mantengan eficacia.','Código Civil, art. 2013');
add('registral',0,'Ana está inscrita; Bruno le compra y Carla compra a Bruno. ¿Qué principio exige la inscripción del eslabón de Bruno?','Tracto sucesivo.','Libre competencia.','Inmediación penal.','Gratuidad de la inscripción.','El tracto exige continuidad entre quien transmite y quien recibe.','Código Civil, art. 2015');
add('registral',0,'Dos hipotecas compatibles ingresan en horarios distintos. ¿Cuál es el principio que organiza su rango?','Prioridad preferente.','Prioridad excluyente en todo supuesto.','Buena costumbre comercial.','Título posesorio.','La prioridad preferente ordena derechos compatibles por presentación, con salvedades legales.','Código Civil, art. 2016');
add('registral',0,'Dos ventas incompatibles del mismo inmueble pretenden inscribirse. ¿Qué principio resulta central?','Prioridad excluyente.','Sucesión intestada.','Reserva de dominio de vehículos.','Silencio positivo administrativo.','No debe inscribirse un título incompatible con otro prioritario inscrito o pendiente.','Código Civil, art. 2017');
// REGISTRAL · arena 1
add('registral',1,'¿Qué documento se consulta para revisar el sustento documental de un asiento registral?','El título archivado.','El recibo de agua del comprador.','La boleta de pago de un trabajador.','La licencia municipal en todo caso.','Los títulos archivados contienen documentación que sustentó inscripciones.','Reglamento General de los Registros Públicos');
add('registral',1,'Un título presenta un defecto subsanable detectado en la calificación. ¿Qué respuesta registral puede corresponder?','Una observación que permita subsanar conforme al procedimiento.','Inscripción obligatoria sin revisar el título.','Sentencia penal del registrador.','Cierre permanente de la partida.','El registrador califica y puede formular observaciones por defectos subsanables.','Reglamento General de los Registros Públicos');
add('registral',1,'Un ciudadano quiere conocer quién figura como titular registral. ¿Qué herramienta es pertinente?','La publicidad registral de la partida respectiva.','El historial de mensajes privados del vendedor.','La simple posesión del inmueble.','Una constancia electoral.','La publicidad registral permite conocer información registral dentro de las reglas aplicables.','Reglamento General de los Registros Públicos');
add('registral',1,'¿Cuál es la finalidad principal de la calificación registral?','Evaluar si el título cumple los requisitos jurídicos para acceder al Registro.','Resolver cualquier litigio judicial de propiedad.','Garantizar el éxito económico de la compra.','Fijar el precio de todos los inmuebles.','La calificación se rige por competencias y criterios registrales, no reemplaza al juez.','Reglamento General de los Registros Públicos');
add('registral',1,'Un título se presentó antes, aunque su escritura sea más reciente. ¿Qué dato importa ordinariamente para prioridad?','Fecha y hora de asiento de presentación.','Cantidad de hojas de la escritura.','Antigüedad del DNI del comprador.','Número de copias del contrato.','La prioridad registral se vincula al asiento de presentación.','Reglamento General de los Registros Públicos, principio IX');
// REGISTRAL · arena 2
add('registral',2,'Se pide primera inscripción de un predio que nunca estuvo inscrito. ¿Cómo se denomina?','Inmatriculación.','Rectificación de nombre.','Cancelación por caducidad.','Anotación de demanda penal.','La inmatriculación abre la primera partida registral del inmueble.','Código Civil, art. 2018');
add('registral',2,'Una escritura pública de seis años sustenta una primera inscripción y cumple requisitos técnicos. ¿Qué afirmación es posible?','Un solo título puede satisfacer la antigüedad legal general exigida.','Siempre son indispensables exactamente tres títulos.','Nunca puede usarse escritura pública.','La posesión de seis meses es equivalente.','La regulación admite un título con antigüedad suficiente, sujeto a los demás requisitos.','Código Civil, art. 2018');
add('registral',2,'Un asiento contiene un error de escritura evidente y documentado. ¿Qué institución corresponde estudiar?','Rectificación registral.','Usurpación del inmueble.','Sucesión contractual automática.','Arbitraje tributario obligatorio.','Los errores materiales y de concepto tienen procedimientos de rectificación previstos.','Reglamento General de los Registros Públicos');
add('registral',2,'El registrador observa un título. El presentante discrepa de la decisión. ¿Qué órgano resuelve apelaciones registrales?','El Tribunal Registral, conforme al procedimiento aplicable.','La Policía Nacional como segunda instancia.','El Ministerio Público como oficina de calificación.','El notario que emitió el parte en todos los casos.','El Tribunal Registral actúa como segunda instancia administrativa registral.','Reglamento General de los Registros Públicos');
add('registral',2,'Un arrendamiento inscrito debe surtir efectos frente al adquirente del inmueble. ¿Qué función registral se aprecia?','Oponibilidad derivada de la publicidad legalmente prevista.','Conversión de arrendamiento en propiedad.','Anulación de toda compraventa posterior.','Sustitución del contrato por hipoteca.','La inscripción puede proteger la situación del arrendatario ante posteriores adquirentes.','Código Civil, art. 1708');
// REGISTRAL · arena 3
add('registral',3,'Se presentan dos títulos incompatibles con asientos vigentes. ¿Qué tratamiento exige el principio de prioridad?','Respetar la prioridad y el obstáculo de inscripción del título posterior.','Inscribirlos juntos para luego anularlos.','Resolver la propiedad mediante sentencia del registrador.','Priorizar el título con precio más alto.','El procedimiento del título posterior puede quedar suspendido o impedido según las reglas aplicables.','Código Civil, art. 2017; RGRP');
add('registral',3,'Al calificar un título, ¿qué debe distinguirse del análisis judicial del fondo de un litigio?','La competencia legal de calificación frente a controversias reservadas a jueces.','La calificación registral siempre tiene jurisdicción penal.','El registrador puede condenar a prisión.','La inscripción adjudica por sí sola cualquier propiedad discutida.','La calificación no reemplaza las competencias jurisdiccionales.','Reglamento General de los Registros Públicos');
add('registral',3,'Un predio ya está inscrito y se pretende abrir una nueva partida sin sustento de independización. ¿Qué riesgo registral se debe examinar?','Duplicidad de partidas o superposición.','Nacimiento automático de hipoteca.','Donación presumida al Estado.','Cambio de zonificación por silencio.','La identificación del predio y ausencia de superposiciones son importantes para la seguridad registral.','Normativa registral de predios');
add('registral',3,'La publicidad del asiento vigente y la validez del acto causal no coinciden. ¿Qué afirmación es precisa?','El asiento presume legitimidad, pero su inscripción no convalida actos nulos.','La inscripción sana cualquier nulidad.','La sola denuncia elimina automáticamente la partida.','Los títulos archivados nunca importan.','El art. 2013 distingue presunción registral de validez sustantiva.','Código Civil, art. 2013');
add('registral',3,'Una persona ofrece inscripción de un título que no deriva del titular registral. ¿Cuál es el obstáculo habitual?','La ruptura del tracto sucesivo, salvo supuesto exceptuado.','Que la operación sea de monto elevado.','El color de la tinta notarial.','Que el predio tenga un número impar.','Se debe inscribir el derecho del que emana la nueva titularidad.','Código Civil, art. 2015');
// REGISTRAL · arena 4
add('registral',4,'Un adquirente oneroso inscribe, pero el vicio del transferente aparece en un título archivado. ¿Qué efecto tiene para el artículo 2014?','Impide la protección específica prevista cuando la causa consta allí.','Garantiza protección absoluta por pagar.','Vuelve irrelevante revisar títulos previos.','Extingue toda posibilidad de reclamación del transmitente.','La fe pública registral considera asientos y títulos archivados sustentatorios.','Código Civil, art. 2014');
add('registral',4,'Un procedimiento registral recibe un desistimiento. ¿Qué debe verificarse antes de concluir su efecto?','El tipo de desistimiento, legitimación y momento procedimental aplicable.','Que el interesado pague un crédito bancario.','Que la compraventa sea de más de cien páginas.','Que el vendedor haya cambiado de distrito.','El desistimiento registral está sujeto a reglas formales y procedimentales.','Reglamento General de los Registros Públicos');
add('registral',4,'Un interesado sostiene que la fecha notarial basta para ganar el rango entre hipotecas. ¿Cuál es la objeción jurídica?','Debe revisarse el asiento de presentación y las reglas de prioridad.','La firma del notario siempre fija el rango hipotecario.','El monto del impuesto predial determina la prioridad.','La inscripción de hipotecas es declarativa.','La prioridad preferente se retrotrae al asiento de presentación en los términos legales.','Código Civil, art. 2016');
add('registral',4,'Una decisión del Tribunal Registral es cuestionada. ¿Qué principio procedimental corresponde revisar?','El sistema de instancias y las vías de control previstas legalmente.','Una apelación ilimitada ante el mismo registrador.','La intervención exclusiva de un árbitro privado siempre.','La facultad de SUNAT para anular el Tribunal.','Las decisiones registrales tienen cauces procedimentales de revisión definidos por norma.','Reglamento General de los Registros Públicos');
add('registral',4,'Un título pretende inscribir un acto sobre predio indebidamente identificado. ¿Qué importa en calificación?','La identificación registral y técnica suficiente del inmueble.','Solo el nombre comercial del vendedor.','La firma del vecino como único requisito.','El tamaño del sobre donde va el título.','La determinación del predio es esencial para extender inscripciones seguras.','Normativa del Registro de Predios');
// REGISTRAL · arena 5
add('registral',5,'Dos adquisiciones enfrentadas tienen escrituras, títulos archivados y presentaciones en fechas distintas. ¿Qué análisis es imprescindible?','Integrar tracto, prioridad, legitimación y fe pública según hechos probados.','Elegir automáticamente al precio mayor.','Decidir según la edad del comprador.','Inscribir ambos derechos exclusivos sobre el mismo total.','Los principios registrales interactúan; ninguno reemplaza el examen jurídico del caso.','Código Civil, arts. 2013–2017');
add('registral',5,'Un tercero afirma buena fe pese a constar el defecto en archivo registral. ¿Qué error de enfoque debe evitarse?','Reducir buena fe registral a la afirmación personal de desconocimiento.','Revisar información del registro.','Examinar la onerosidad del negocio.','Comprobar si hubo inscripción.','La ley establece requisitos objetivos de protección y relevancia de títulos archivados.','Código Civil, art. 2014');
add('registral',5,'El título A bloquea a B pero finalmente caduca su presentación. ¿Qué cuestión debe reexaminarse?','Si subsiste el obstáculo de prioridad frente a B en su estado actual.','Si B paga mayor precio.','Si el notario de A es más antiguo.','Si se borran todos los derechos del propietario.','La vigencia del título prioritario incide en el tratamiento del posterior.','Reglamento General de los Registros Públicos');
add('registral',5,'Un asiento presume un derecho mientras el contrato causal es impugnado. ¿Cuál es la distinción más rigurosa?','Presunción registral, invalidez del acto y eventual protección del tercero tienen presupuestos propios.','Toda impugnación suspende automáticamente los efectos.','La inscripción impide cualquier demanda.','Una anotación informal elimina por sí sola la partida.','Los artículos 2013 y 2014 tratan instituciones relacionadas pero diferentes.','Código Civil, arts. 2013 y 2014');
add('registral',5,'Un registrador recibe un título de independización y otro de transferencia sobre áreas discutidas. ¿Qué debe priorizar?','Calificación de identidad predial, tracto y compatibilidad conforme a normas aplicables.','Solo la preferencia verbal del interesado.','El volumen de los expedientes.','La cantidad de testigos no registrales como criterio único.','Las transferencias y modificaciones físicas requieren correspondencia registral y técnica.','Reglamento del Registro de Predios');
// PENAL · arena 0
add('penal',0,'¿Qué principio exige que una conducta delictiva esté prevista en una ley aplicable?','Legalidad penal.','Prioridad registral.','Tracto sucesivo.','Libertad contractual absoluta.','No debe imponerse pena por una conducta no prevista como delito según el principio de legalidad.','Código Penal, título preliminar');
add('penal',0,'Una persona es investigada penalmente. ¿Qué debe presumirse mientras no exista condena conforme a ley?','Su inocencia.','Su culpabilidad definitiva.','La pérdida de todos sus bienes.','La validez de toda prueba ilegal.','La presunción de inocencia impide equiparar investigación con condena.','Constitución Política del Perú');
add('penal',0,'¿Qué idea define mejor el dolo en términos generales?','Conocimiento y voluntad de realizar el hecho típico, según el supuesto.','Ausencia necesaria de conciencia.','Toda conducta que ocasiona daños sin excepción.','Una inscripción registral defectuosa.','El dolo se distingue de la culpa y requiere análisis del tipo y el caso.','Código Penal, parte general');
add('penal',0,'Una persona no paga una deuda comercial. ¿Qué conclusión es correcta?','El incumplimiento no constituye automáticamente estafa.','Siempre es un delito penal.','Basta una denuncia para condenar.','El Registro declara prisión automáticamente.','Los elementos de estafa no se infieren solo del impago contractual.','Código Penal, delitos patrimoniales');
add('penal',0,'¿Qué bien jurídico se relaciona con la falsificación de documentos?','La fe pública.','La propiedad intelectual exclusivamente.','Solo la libertad de tránsito.','Únicamente el orden urbanístico.','La autenticidad y confianza documental son aspectos tutelados por los delitos contra la fe pública.','Código Penal, delitos contra la fe pública');
// PENAL · arena 1
add('penal',1,'Una persona fabrica un documento falso que aparenta ser auténtico. ¿Qué figura conviene examinar?','Falsificación documental material.','Donación inmobiliaria.','Tracto sucesivo.','Silencio administrativo.','La creación o adulteración material del documento puede ser penalmente relevante.','Código Penal, falsificación de documentos');
add('penal',1,'Un documento auténtico contiene declaraciones falsas relevantes. ¿Qué institución puede ser pertinente según sus presupuestos?','Falsedad ideológica.','Independización de predios.','Hipoteca legal automática.','Desistimiento registral.','No es lo mismo falsificar físicamente el documento que insertar falsedades en su contenido.','Código Penal, delitos de falsedad');
add('penal',1,'Una persona ocupa un inmueble mediante medios que encuadrarían en un tipo penal de despojo. ¿Qué figura investigar?','Usurpación, según sus elementos legales.','Solo lesión contractual.','Subrogación del arrendador.','Inscripción de representación.','El delito de usurpación exige examinar modalidades típicas y pruebas del supuesto.','Código Penal, usurpación');
add('penal',1,'En un supuesto de estafa, ¿qué aspecto suele ser relevante para el análisis típico?','El engaño penalmente relevante y la disposición patrimonial, entre otros elementos.','Que toda deuda tenga un interés elevado.','Que cualquier contrato sea privado.','Que el bien no tenga partida registral.','El engaño y el perjuicio patrimonial requieren análisis concreto; no toda deuda impaga configura delito.','Código Penal, estafa');
add('penal',1,'¿Qué diferencia general hay entre culpa y dolo?','La estructura subjetiva y las exigencias del tipo penal difieren.','Son siempre conceptos jurídicamente idénticos.','Culpa exige siempre intención de delinquir.','Dolo significa siempre accidente inevitable.','La responsabilidad subjetiva se examina según dolo, culpa y tipicidad del hecho.','Código Penal, parte general');
// PENAL · arena 2
add('penal',2,'Un funcionario consigna un hecho falso en instrumento auténtico, en circunstancias típicas. ¿Qué debe valorarse?','Si concurren los elementos de falsedad ideológica.','Si el papel es blanco.','Si el instrumento fue firmado con bolígrafo.','Si el autor prefiere documentos privados.','La falsedad ideológica exige analizar la autenticidad instrumental y el contenido que debe probar.','Código Penal, falsedad ideológica');
add('penal',2,'Un sujeto comienza a ejecutar un delito, pero este no llega a consumarse por causas ajenas. ¿Qué categoría general estudiar?','Tentativa.','Donación de bienes inmuebles.','Prioridad preferente.','Inmatriculación.','La tentativa requiere examinar inicio de ejecución y ausencia de consumación según la norma.','Código Penal, parte general');
add('penal',2,'Dos personas intervienen en un hecho punible de formas diferentes. ¿Qué debe distinguirse?','Autoría y participación según sus aportes.','Que todos son siempre autores principales.','Que ninguno puede responder.','Que la sentencia se decide por antigüedad laboral.','La responsabilidad no depende solo de estar presente: importa el aporte y la imputación.','Código Penal, autoría y participación');
add('penal',2,'Una prueba documental se sospecha adulterada. ¿Qué enfoque resulta razonable?','Verificar autenticidad, cadena de custodia y pertinencia de pericia según el caso.','Condenar sin contrastar ninguna prueba.','Considerar falsa toda fotocopia.','Anular automáticamente todos los títulos del acusado.','La autenticidad documental puede requerir actividad probatoria adecuada.','Garantías del proceso penal');
add('penal',2,'Un incumplimiento contractual se denuncia como estafa sin indicios de engaño inicial. ¿Qué diferencia es clave?','Distinguir el conflicto civil de los elementos del tipo penal de estafa.','Suponer estafa por el solo retraso.','Confundir deuda con falsificación material.','Presumir que toda denuncia prueba culpabilidad.','El análisis debe abarcar el engaño y los demás elementos típicos, no solo la falta de pago.','Código Penal, delitos patrimoniales');
// PENAL · arena 3
add('penal',3,'Se altera una escritura auténtica y luego se usa ante el Registro. ¿Qué debe diferenciar la investigación?','Falsificación material, uso y eventual concurso según hechos y norma.','Únicamente el color de la hoja.','Solo la fecha de pago de predial.','Que siempre existe un único delito sin análisis.','Los actos de falsificación y empleo del documento requieren calificación típica concreta.','Código Penal, delitos de falsedad');
add('penal',3,'Dos personas contribuyen a una falsedad: una crea el documento y otra lo presenta con conocimiento. ¿Qué análisis corresponde?','Individualizar conductas, dolo y posibles formas de intervención.','Atribuir idéntica responsabilidad sin examinar hechos.','Considerar inocentes a ambos por ser dos.','Sustituir toda prueba por el asiento registral.','La imputación penal exige analizar cada aporte y sus elementos subjetivos.','Código Penal, autoría y participación');
add('penal',3,'Un proceso penal contiene una única prueba obtenida ilegalmente. ¿Qué principio exige atención?','Garantías del debido proceso y licitud probatoria.','Prioridad preferente hipotecaria.','Prescripción adquisitiva de bienes.','Autonomía registral de toda prueba.','La eficacia de la prueba debe evaluarse conforme a garantías constitucionales y procesales.','Constitución y proceso penal');
add('penal',3,'Un sujeto intenta justificar un hecho alegando legítima defensa. ¿Qué se necesita?','Examinar los requisitos legales de la causa de justificación según los hechos.','Aceptar cualquier alegación sin verificar.','Exigir que el hecho esté inscrito en SUNARP.','Analizar solo la propiedad del arma.','Las causas de justificación requieren presupuestos específicos.','Código Penal, legítima defensa');
add('penal',3,'Se denuncia usurpación tras una controversia sobre títulos de propiedad. ¿Qué precaución es esencial?','Separar la titularidad civil de la configuración penal concreta del despojo.','Afirmar que toda controversia de títulos prueba usurpación.','Ignorar los hechos posesorios.','Dar por condenado al titular no inscrito.','Un litigio dominial no resuelve automáticamente la tipicidad penal.','Código Penal, usurpación');
// PENAL · arena 4
add('penal',4,'Un instrumento notarial es auténtico, pero contiene una declaración contraria a la verdad. ¿Qué examen penal procede?','Determinar si la falsedad cumple elementos de la figura ideológica aplicable.','Tratarlo como falsificación material en todos los casos.','Descartar siempre cualquier relevancia penal.','Concluir culpabilidad únicamente por la discrepancia.','La falsedad ideológica tiene requisitos propios, diferenciados de la adulteración física.','Código Penal, delitos de falsedad');
add('penal',4,'Una firma se atribuye a alguien que niega haberla puesto. ¿Qué enfoque probatorio es correcto?','Evaluar autenticidad y autoría mediante medios idóneos, con respeto del debido proceso.','Dar por culpable al primer presentante.','Declarar nulo de oficio cualquier inmueble.','Presumir auténtica una firma por llevar tinta azul.','La atribución penal requiere prueba y no se presume por un único indicio.','Garantías del proceso penal');
add('penal',4,'Un tercero presenta un documento falsificado ignorando genuinamente la falsedad. ¿Qué dimensión importa?','El conocimiento exigido por la figura penal eventualmente imputada.','Que usar un papel siempre genera dolo.','Que la presentación conlleva prisión automática.','Que la inscripción corrige cualquier falsedad.','La tipicidad subjetiva debe examinarse según el comportamiento concreto.','Código Penal, parte general');
add('penal',4,'Se discute si hubo complicidad o coautoría en un fraude documental. ¿Qué debe analizarse?','La naturaleza del aporte, acuerdo e intervención conforme a la teoría del delito.','Solo el orden alfabético de los investigados.','La edad del documento como único factor.','La titularidad del inmueble sin atender conductas.','La delimitación entre autoría y participación demanda examen individualizado.','Código Penal, autoría y participación');
add('penal',4,'Una denuncia afirma que la falsedad documental produjo un daño económico. ¿Qué planos deben mantenerse separados?','Tipicidad y culpabilidad penal, reparación civil y consecuencias registrales.','Todo efecto es necesariamente penal.','La reparación civil exige siempre nueva hipoteca.','La falsedad cancela automáticamente asientos.','La responsabilidad penal y los efectos patrimoniales o registrales siguen reglas distintas.','Código Penal; Código Civil; normativa registral');
// PENAL · arena 5
add('penal',5,'Se utilizó escritura adulterada para aparentar transmisión y un tercero dice haber comprado de buena fe. ¿Qué análisis conjunto es indispensable?','Responsabilidad por falsedad, efectos civiles y protección registral del tercero por separado.','Afirmar que una inscripción elimina cualquier delito.','Condenar automáticamente a todo comprador posterior.','Dar por válido todo negocio porque hay asiento.','Lo penal, civil y registral pueden interactuar sin confundirse sus presupuestos.','Código Penal, Código Civil y normas registrales');
add('penal',5,'Un supuesto fraude utiliza instrumento auténtico con contenido falso y posteriores transferencias. ¿Qué clasificación inicial es rigurosa?','Distinguir naturaleza del documento, posible falsedad de contenido, autoría y efectos jurídicos.','Afirmar falsificación material en todo caso.','Prescindir de la investigación de los otorgantes.','Tomar la inscripción como sentencia condenatoria.','La calificación depende de modalidad documental y hechos probados.','Código Penal, falsedad');
add('penal',5,'La fiscalía presenta varias pericias contradictorias sobre una firma. ¿Qué principio guía la decisión?','Valoración motivada de toda la prueba con presunción de inocencia.','Elegir necesariamente la pericia de fecha más antigua.','Condenar por mayoría simple de expertos.','Pedir a SUNARP que declare culpabilidad.','La prueba contradictoria se valora conjuntamente bajo garantías procesales.','Constitución; proceso penal');
add('penal',5,'La apropiación de un inmueble se relata como delito y como incumplimiento civil. ¿Qué se debe determinar primero?','Hechos probados y elementos concretos del tipo penal invocado.','Si el relato usa terminología jurídica compleja.','Si el reclamante conoce al notario.','Cuántas veces aparece el nombre del vendedor.','La frontera civil-penal no se define por el nombre dado a la denuncia.','Código Penal, tipicidad');
add('penal',5,'Un supuesto partícipe sostiene que actuó sin conocer el fraude documental. ¿Cuál es el examen determinante?','Conocimiento, aporte y exigencias de imputación subjetiva y objetiva.','Que toda participación física prueba dolo.','Que la firma digital siempre implica culpabilidad.','Que el registro impide alegar ausencia de dolo.','La responsabilidad personal exige analizar elementos del hecho y de la participación.','Código Penal, parte general');

// NOTARIAL · arena 0
add('notarial',0,'¿Qué instrumento notarial se incorpora al protocolo correspondiente?','La escritura pública.','Una conversación privada no documentada.','Un simple correo sin intervención notarial.','Un recibo bancario cualquiera.','La escritura pública es instrumento protocolar regulado por la Ley del Notariado.','Decreto Legislativo 1049');
add('notarial',0,'¿La legalización de firmas convierte por sí sola un documento privado en escritura pública?','No, son actuaciones notariales distintas.','Sí, siempre.','Sí, si hay dos testigos.','Sí, si el documento tiene más de una página.','La legalización certifica firmas bajo sus reglas; no reemplaza un instrumento protocolar.','Decreto Legislativo 1049');
add('notarial',0,'¿Qué profesional ejerce la función notarial conforme a la normativa peruana?','El notario.','El juez penal en todos los contratos.','El registrador como autor de escrituras.','El recaudador municipal.','El notario es el profesional del derecho facultado para dar fe de actos y contratos en la forma legal.','Decreto Legislativo 1049');
add('notarial',0,'Una persona quiere donar un inmueble. ¿Qué forma especial exige el Código Civil?','Escritura pública.','Solo carta simple.','Una nota de voz.','Un recibo de servicio.','La donación inmobiliaria requiere escritura pública bajo sanción de nulidad.','Código Civil, art. 1625');
add('notarial',0,'¿Cuál es una función típica del parte notarial en trámites ante SUNARP?','Servir como traslado formal del instrumento para su inscripción según las reglas.','Reemplazar cualquier acto jurídico nulo.','Determinar definitivamente la propiedad por sentencia.','Convertir toda deuda en hipoteca.','Los partes notariales son traslados instrumentales relevantes para inscripción.','Decreto Legislativo 1049');
// NOTARIAL · arena 1
add('notarial',1,'La escritura permanece en el protocolo y se expide un traslado. ¿Qué debe diferenciarse?','Matriz y traslado expedido conforme a ley.','Propiedad y delito doloso.','Hipoteca y prescripción.','Partida catastral y DNI.','La matriz es el instrumento original del protocolo; el traslado reproduce su contenido según la normativa.','Decreto Legislativo 1049');
add('notarial',1,'Una persona dice representar a la vendedora. ¿Qué debe examinar el notario?','Identidad y facultades de representación aplicables.','Solo el valor del teléfono del apoderado.','La antigüedad del domicilio del comprador.','Exclusivamente la firma del comprador.','La representación exige que el acto esté comprendido en las facultades conferidas.','Código Civil y Decreto Legislativo 1049');
add('notarial',1,'¿Qué finalidad central cumple la identificación de comparecientes?','Verificar quién interviene en el acto notarial conforme a los medios previstos.','Determinar automáticamente solvencia económica.','Garantizar que nunca haya litigios posteriores.','Sustituir la calificación registral de todo acto.','La seguridad de identidad integra las obligaciones notariales.','Decreto Legislativo 1049');
add('notarial',1,'¿Un poder para administrar bienes implica siempre poder para vender inmuebles?','No, debe revisarse el alcance de las facultades otorgadas.','Sí, siempre.','Sí, si el apoderado conoce al notario.','Sí, si el bien tiene partida registral.','La representación para actos de disposición exige facultades suficientes.','Código Civil, representación');
add('notarial',1,'Un documento tiene firmas legalizadas. ¿Qué afirmación es más precisa?','La intervención notarial sobre la firma no prueba por sí sola la validez de todo el contenido.','Todo contenido se vuelve jurídicamente incuestionable.','La firma legalizada convierte todo bien en inmueble.','Nace automáticamente una hipoteca.','La certificación de firmas y la validez sustantiva del negocio son materias distintas.','Normativa notarial');
// NOTARIAL · arena 2
add('notarial',2,'Se presenta una copia simple de escritura donde SUNARP exige parte notarial. ¿Qué debe evaluarse?','Si el documento presentado reúne la forma legal de título inscribible.','Que cualquier copia simple obliga a registrar.','Que el juez debe escribir una nueva minuta.','Que basta una fotografía del notario.','La inscripción exige forma documental idónea según el acto y registro.','Reglamento registral y normativa notarial');
add('notarial',2,'Un compareciente no puede actuar válidamente por sí mismo en determinado acto. ¿Qué elemento importa?','Régimen de capacidad y representación aplicable al acto.','El color del sello usado.','Que otro compareciente tenga casa propia.','Solo la antigüedad del instrumento.','La capacidad y representación determinan quién puede intervenir válidamente.','Código Civil; Decreto Legislativo 1049');
add('notarial',2,'Un otorgante manifiesta querer vender un bien que no le pertenece. ¿Qué debe distinguir el operador jurídico?','Declaración documentada, legitimación del transferente y efectos del negocio.','Que la intervención notarial transfiere siempre dominio ajeno.','Que la firma cura cualquier falta de legitimación.','Que todos los contratos son inexistentes si son notariales.','La fe notarial no convierte automáticamente en propietario a quien no lo es.','Código Civil y normativa notarial');
add('notarial',2,'Un notario expide testimonio y parte de una misma escritura. ¿Qué diferencia general existe?','Son modalidades distintas de traslado documental con finalidades legales propias.','Ambos son sentencias judiciales.','La matriz sale obligatoriamente del protocolo.','El testimonio crea por sí solo un acto jurídico nuevo.','Las normas notariales regulan diferentes traslados instrumentales.','Decreto Legislativo 1049');
add('notarial',2,'Se solicita insertar una declaración de falso contenido en escritura. ¿Qué debe tenerse presente?','Los deberes notariales y las posibles consecuencias civiles y penales.','Que cualquier declaración es inmune al control legal.','Que lo firmado nunca tiene trascendencia jurídica.','Que una firma falsa es aceptable con autorización oral.','La fe pública requiere actuar dentro de las normas y deberes profesionales.','Normativa notarial y Código Penal');
// NOTARIAL · arena 3
add('notarial',3,'Un apoderado comparece con poder para administrar, pero pretende donar un inmueble. ¿Qué debe evaluarse?','Facultades suficientes de disposición y forma solemne de la donación.','Solo la identidad del notario.','Que administrar comprende necesariamente toda donación.','Que la donación no necesita escritura.','Representación y forma del negocio son exigencias independientes que deben concurrir.','Código Civil, representación y art. 1625');
add('notarial',3,'Una escritura identifica un inmueble de modo contradictorio con la partida. ¿Qué análisis corresponde?','Correspondencia de identificación predial y posibilidad de rectificación conforme a la ley.','Registrar sin revisar por ser escritura pública.','Eliminar la partida registral completa.','Dar validez a ambas descripciones sin condición.','Instrumentación y calificación requieren precisión en la identidad del inmueble.','Normativa notarial y registral');
add('notarial',3,'Una discrepancia de nombres afecta a un otorgante. ¿Qué precaución es jurídica?','Comprobar identidad con medios idóneos y evaluar regularización documental.','Resolverlo por preferencia estética del nombre.','Sustituir toda verificación por una llamada informal.','Considerar que ningún nombre importa.','La identificación insuficiente afecta la seguridad del acto notarial.','Decreto Legislativo 1049');
add('notarial',3,'La minuta y escritura contienen cláusulas que parecen incompatibles. ¿Qué debe examinarse?','Contenido del instrumento autorizado y las reglas sobre rectificación e interpretación.','Únicamente el tamaño de letra.','Solo quién llevó el papel a notaría.','Que siempre hay nulidad sin estudiar el caso.','Es preciso precisar el contenido jurídico formalizado y sus posibles defectos.','Código Civil y normativa notarial');
add('notarial',3,'Se pretende otorgar escritura a nombre de quien falleció antes del otorgamiento. ¿Qué asuntos deben examinarse?','Capacidad, representación y eventuales vías sucesorias aplicables.','Que la firma del fallecido se presume válida.','Que todo poder continúa indefinidamente.','Que la muerte hace innecesario el registro.','La muerte del representado puede incidir en la representación y requiere evaluación conforme a ley.','Código Civil; sucesiones y representación');
// NOTARIAL · arena 4
add('notarial',4,'Una escritura pública de hipoteca se otorgó válidamente pero no se inscribió. ¿Qué distinción jurídica debe hacerse?','Forma instrumental válida no equivale a hipoteca real válidamente constituida.','La escritura crea siempre el gravamen sin inscripción.','El préstamo es automáticamente nulo.','La inscripción solo es necesaria si hay juicio.','La hipoteca exige inscripción como requisito de validez, aparte de su instrumentación.','Código Civil, art. 1099');
add('notarial',4,'Una escritura documenta negocio simulado con aparente voluntad distinta de la real. ¿Qué análisis procede?','Posible simulación civil y consecuencias aplicables sin confundir la función documental.','Asumir que la forma pública hace verdadera toda intención.','Declarar inexistente la normativa civil.','Concluir delito automático sin prueba.','La intervención notarial no elimina el posible examen de simulación del negocio.','Código Civil, simulación');
add('notarial',4,'Un poder inscrito contiene una limitación y se presenta escritura que la excede. ¿Qué debe revisarse?','Alcance de representación, contenido instrumental y legitimación registral.','Solo el monto del arancel notarial.','La firma del comprador como único requisito.','Que los poderes inscritos no pueden limitarse.','El poder debe examinarse frente al acto y su oponibilidad registral.','Código Civil, representación; normas registrales');
add('notarial',4,'Un tercero sostiene que un documento con firma legalizada acredita indiscutiblemente propiedad. ¿Qué respuesta es correcta?','La legalización de firmas no determina por sí sola titularidad ni validez del negocio.','Toda firma legalizada acredita dominio pleno.','Toda firma legalizada constituye hipoteca.','El registrador no puede evaluar título con firma legalizada.','La autenticación de firma tiene alcance distinto de titularidad real.','Normativa notarial y Código Civil');
add('notarial',4,'Aparece presunta falsificación de una escritura y existen asientos posteriores. ¿Qué planos se deben separar?','Autenticidad instrumental, responsabilidad y efectos civiles/registrales sobre terceros.','Solo la responsabilidad laboral del digitador.','Aceptar toda anotación como definitiva.','Cancelar todas las partidas sin procedimiento.','La falsedad y los efectos sobre adquisiciones posteriores requieren análisis diferenciado.','Código Penal, Código Civil y normativa notarial');
// NOTARIAL · arena 5
add('notarial',5,'Un falso representante otorga escritura; luego el título se inscribe y se transmite a un tercero. ¿Qué enfoque integra mejor el caso?','Identidad, representación, invalidez o ineficacia y fe pública registral del tercero.','Suponer que la inscripción subsana cualquier representación.','Atribuir al notario poderes legislativos.','Resolver solo con la posesión del comprador.','La cadena de negocios exige revisar cada etapa y la eventual protección registral.','Código Civil, arts. 2013–2014; normativa notarial');
add('notarial',5,'Un documento privado supuestamente donativo se eleva de manera tardía a escritura. ¿Qué exige la evaluación?','Revisar si y cuándo se cumplieron realmente las formalidades del negocio.','Considerar válida toda donación privada desde siempre.','Desestimar automáticamente el análisis de las voluntades.','Tratarla como hipoteca inscrita.','El acto de donación inmobiliaria requiere formalidad solemne y sus efectos deben estudiarse concretamente.','Código Civil, art. 1625');
add('notarial',5,'Una escritura contiene cláusula ambigua de disposición y existe poder limitativo. ¿Qué debe coordinar el análisis?','Interpretación contractual y alcance del mandato respecto del acto autorizado.','Solo el precio declarado.','La opinión de un testigo como regla única.','La apariencia estética de la escritura.','Interpretar el negocio exige integrar condiciones del acto y facultades representativas.','Código Civil, interpretación y representación');
add('notarial',5,'El parte presentado a SUNARP difiere materialmente de la matriz protocolar. ¿Qué actuación requiere atención?','Cotejo del instrumento, corrección formal y eventuales responsabilidades según el caso.','Inscribir sin cuestionar la discrepancia.','Tomar cualquier copia como matriz.','Desconocer el deber de autenticidad documental.','La fidelidad del traslado a la matriz resulta esencial para la seguridad jurídica.','Decreto Legislativo 1049');
add('notarial',5,'Un mismo bien presenta problemas de identidad, gravámenes y representación en escritura compleja. ¿Qué debe verificar el operador?','Título del otorgante, facultades, identificación del predio y afectaciones existentes.','Solo el monto del derecho notarial.','Únicamente la antigüedad de los vecinos.','Que las partes coincidan en su vestimenta.','Una operación compleja combina distintas exigencias de capacidad, contenido y publicidad.','Código Civil y normativa registral/notarial');
// ADMINISTRATIVO · arena 0
add('administrativo',0,'¿Qué norma organiza de manera general el procedimiento administrativo en el Perú?','La Ley 27444 y su Texto Único Ordenado.','El Código Penal exclusivamente.','Un contrato privado entre vecinos.','El reglamento de una asociación deportiva.','La Ley del Procedimiento Administrativo General es marco básico para actuaciones administrativas.','TUO de la Ley 27444');
add('administrativo',0,'Una entidad emite una resolución sin explicar los motivos. ¿Qué deber debe examinarse?','Motivación del acto administrativo.','Tracto sucesivo.','Inmatriculación.','Pacto de arrendamiento.','La motivación relaciona fundamentos de hecho y derecho con la decisión.','TUO de la Ley 27444');
add('administrativo',0,'¿Cuál es una finalidad de la notificación administrativa?','Dar conocimiento formal del acto y permitir ejercer derechos según el procedimiento.','Convertir toda solicitud en demanda penal.','Constituir hipotecas automáticamente.','Reemplazar la competencia del órgano.','La notificación es relevante para la eficacia del acto y la defensa del administrado.','TUO de la Ley 27444');
add('administrativo',0,'Un administrado discrepa con una decisión impugnable. ¿Qué herramienta general puede existir?','Un recurso administrativo conforme a la ley.','Una compraventa obligatoria.','Una escritura de hipoteca por desacuerdo.','Una multa privada al funcionario.','Los recursos administrativos tienen requisitos, órganos y plazos legales.','TUO de la Ley 27444');
add('administrativo',0,'¿Qué significa que una entidad actúe dentro de su competencia?','Que ejerce facultades atribuidas por el ordenamiento.','Que puede decidir cualquier asunto sin norma.','Que reemplaza a todos los jueces.','Que no debe motivar nunca.','La competencia es un requisito de validez del acto administrativo.','TUO de la Ley 27444');
// ADMINISTRATIVO · arena 1
add('administrativo',1,'Una entidad solicita documentos innecesarios no previstos conforme a su marco aplicable. ¿Qué principios pueden ser relevantes?','Legalidad, razonabilidad y simplificación administrativa.','Prioridad hipotecaria únicamente.','Autonomía testamentaria.','Tipicidad penal del comprador.','La Administración debe sujetar sus requisitos a normas y principios aplicables.','TUO de la Ley 27444');
add('administrativo',1,'Un recurso busca que el órgano superior revise una decisión. ¿Qué figura general corresponde evaluar?','Apelación administrativa, cuando proceda.','Testamento notarial.','Inmatriculación de vehículos.','Cancelación de hipoteca por sí sola.','El recurso de apelación se dirige a la revisión superior conforme a su régimen.','TUO de la Ley 27444');
add('administrativo',1,'¿Qué debe contener una motivación adecuada en términos generales?','Razones fácticas y jurídicas pertinentes al caso.','Solo una frase genérica de conformidad.','Únicamente la firma del solicitante.','Un texto sin relación con la decisión.','La motivación debe sustentar la decisión en el expediente y el ordenamiento.','TUO de la Ley 27444');
add('administrativo',1,'Una autoridad sanciona sin dar oportunidad de defensa. ¿Qué principio compromete?','Debido procedimiento.','Tracto sucesivo.','Tradición de inmueble.','Prioridad preferente.','Las garantías de defensa deben observarse en los procedimientos aplicables.','TUO de la Ley 27444');
add('administrativo',1,'La notificación de un acto es defectuosa. ¿Qué cuestión debe analizarse?','Las reglas de notificación y sus efectos en plazos y defensa.','El color del documento administrativo.','La marca de impresora.','La edad del edificio administrativo.','Las notificaciones cumplen funciones jurídicas y afectan el ejercicio de derechos.','TUO de la Ley 27444');
// ADMINISTRATIVO · arena 2
add('administrativo',2,'Un órgano emite acto fuera de sus facultades. ¿Qué requisito legal se cuestiona?','Competencia.','Posesión física del inmueble.','Hipoteca registral.','Legalización notarial de firmas.','La competencia es uno de los requisitos de validez del acto administrativo.','TUO de la Ley 27444');
add('administrativo',2,'¿Qué diferencia central existe entre error material y causal de nulidad?','Un error corregible no equivale necesariamente a un vicio invalidante.','Todo error tipográfico anula automáticamente toda resolución.','Ningún acto admite rectificación.','Solo los jueces pueden cambiar una coma de cualquier resolución.','La rectificación de errores materiales tiene régimen distinto de la nulidad.','TUO de la Ley 27444');
add('administrativo',2,'Se interpone un recurso fuera del plazo legal. ¿Qué debe considerar la entidad?','Requisitos de admisibilidad y efectos del vencimiento del plazo.','La fecha de nacimiento del notario.','Solo la simpatía del funcionario.','Que todos los recursos son eternamente oportunos.','Los medios impugnatorios están sujetos a reglas temporales.','TUO de la Ley 27444');
add('administrativo',2,'Una resolución no valora los argumentos centrales del administrado. ¿Qué garantía podría afectarse?','Debida motivación y derecho de defensa según el caso.','Regla de hipoteca constitutiva.','Inscripción testamentaria.','Reserva del folio real.','La motivación debe atender a las cuestiones relevantes que sustentan la decisión.','TUO de la Ley 27444');
add('administrativo',2,'Una entidad impone sanción administrativa y un juez examina un delito relacionado. ¿Qué debe evitarse?','Confundir automáticamente la responsabilidad administrativa con la penal.','Distinguir tipos de responsabilidad.','Analizar la competencia.','Revisar garantías del procedimiento.','Las vías sancionadoras pueden tener presupuestos diferentes y límites legales.','TUO de la Ley 27444 y Código Penal');
// ADMINISTRATIVO · arena 3
add('administrativo',3,'Un acto fue expedido por órgano incompetente y produjo efectos. ¿Qué análisis es necesario?','Examinar causal de nulidad, procedimiento de declaración y efectos legales.','Declarar que todo acto es válido por producir efectos.','Sustituir la revisión jurídica por opinión pública.','Registrar un título inmobiliario para sanar competencia.','Los efectos de un acto no eliminan el deber de examinar su validez jurídica.','TUO de la Ley 27444');
add('administrativo',3,'Una solicitud se tramita bajo un régimen de silencio administrativo. ¿Qué se debe verificar?','La calificación legal del procedimiento y condiciones para el efecto del silencio.','Suponer que el silencio es positivo siempre.','Suponer que el silencio es negativo siempre.','Ignorar el TUPA y normas especiales.','La consecuencia del silencio depende del régimen aplicable y sus excepciones.','TUO de la Ley 27444');
add('administrativo',3,'Una resolución administrativa invoca la norma correcta pero ignora hechos probados relevantes. ¿Qué vicio puede plantearse?','Defecto de motivación y valoración fáctica.','Hipoteca tácita.','Título archivado falso por definición.','Usufructo legal automático.','La motivación debe justificar la subsunción de hechos en normas.','TUO de la Ley 27444');
add('administrativo',3,'Un servidor pretende modificar un acto firme sin seguir procedimiento. ¿Qué debe considerarse?','Reglas específicas de nulidad, revocación y revisión de oficio.','Libertad absoluta para cambiar decisiones.','Que todos los actos se corrigen con teléfono.','Que ningún acto administrativo tiene estabilidad.','Los mecanismos de revisión de actos están delimitados legalmente.','TUO de la Ley 27444');
add('administrativo',3,'Una sanción se fundamenta en conducta que no está prevista como infracción aplicable. ¿Qué principio importa?','Tipicidad en potestad sancionadora.','Tradición posesoria.','Fe pública registral de inmuebles.','Régimen de servidumbres.','La sanción administrativa exige infracción prevista en el marco normativo correspondiente.','TUO de la Ley 27444');
// ADMINISTRATIVO · arena 4
add('administrativo',4,'Una autoridad dicta sanción sin competencia y omite notificarla adecuadamente. ¿Qué enfoque procede?','Analizar separadamente validez del acto y eficacia/notificación.','Tratar todos los defectos como el mismo fenómeno.','Afirmar que la notificación subsana la competencia.','Concluir que no cabe ninguna impugnación.','Competencia y notificación cumplen funciones jurídicas distintas.','TUO de la Ley 27444');
add('administrativo',4,'Una resolución de segunda instancia confirma sin responder agravios sustanciales. ¿Qué dimensión puede cuestionarse?','Suficiencia de motivación y derecho a obtener decisión fundada.','Validez de cualquier hipoteca.','Fecha de la compraventa del administrado.','Antigüedad del asiento registral.','La decisión impugnatoria debe justificar su conclusión conforme a exigencias aplicables.','TUO de la Ley 27444');
add('administrativo',4,'Un procedimiento tiene norma especial y reglas generales de la Ley 27444. ¿Qué análisis exige?','Articular régimen especial y garantías generales conforme al ordenamiento.','Ignorar siempre la norma especial.','Usar exclusivamente el Código Civil para todo trámite.','Dejar decidir libremente a cualquier funcionario.','La especialidad normativa no significa ausencia de garantías generales.','TUO de la Ley 27444');
add('administrativo',4,'Un acto fue emitido irregularmente pero beneficia a terceros. ¿Qué cuestión jurídica surge ante revisión?','Efectos, límites y garantías aplicables al mecanismo de invalidación.','Que nunca pueda analizarse su validez.','Que la simple queja elimina derechos automáticamente.','Que todas las situaciones son irrevisables.','La invalidez y sus efectos deben analizarse conforme al procedimiento y protección legal pertinente.','TUO de la Ley 27444');
add('administrativo',4,'Una multa se fija sin valorar criterios de proporcionalidad aplicables. ¿Qué principio puede vulnerarse?','Razonabilidad de la potestad sancionadora.','Tracto sucesivo.','Fe pública notarial.','Hipoteca constitutiva.','La potestad sancionadora está sometida a criterios legales de razonabilidad.','TUO de la Ley 27444');
// ADMINISTRATIVO · arena 5
add('administrativo',5,'Una entidad resuelve solicitud de derecho registral con motivación aparente y órgano dudoso. ¿Qué examen combina los planos correctos?','Competencia, motivación, procedimiento y eventual control de legalidad.','Únicamente la simpatía de las partes.','Solo el precio del inmueble.','Que toda motivación aparente es suficiente.','Los requisitos de validez administrativa deben evaluarse conjuntamente según el caso.','TUO de la Ley 27444');
add('administrativo',5,'Un título registral es observado por la Administración y se impugna. ¿Qué distinción institucional importa?','Procedimiento registral especial y reglas de impugnación dentro de su marco jurídico.','Tratarlo siempre como apelación penal.','Desconocer por completo competencias del Tribunal Registral.','Suponer que el notario resuelve todas las apelaciones.','La especialidad del procedimiento registral exige atender a sus propias instancias y normativa.','RGRP y TUO de la Ley 27444');
add('administrativo',5,'Una sanción administrativa deriva de documento presuntamente falso. ¿Qué separación analítica es indispensable?','Validez del procedimiento sancionador, prueba y eventual delito independiente.','Condenar penalmente desde el procedimiento sin juicio.','Ignorar que hay distintas autoridades competentes.','Suponer que la falsedad elimina todas las garantías.','Responsabilidad administrativa y penal requieren competencia y elementos propios.','TUO de la Ley 27444; Código Penal');
add('administrativo',5,'Una autoridad revoca acto favorable sin dar intervención a quien podría verse afectado. ¿Qué preocupa?','Garantías procedimentales y requisitos legales de revocación.','Solo el formato de la hoja.','La fecha de nacimiento del beneficiario.','Que el acto no tiene nunca efectos externos.','La revisión o revocación de actos está sometida a límites y garantías.','TUO de la Ley 27444');
add('administrativo',5,'Una entidad decide sobre posesión de un inmueble pero el conflicto de propiedad está judicializado. ¿Qué enfoque es responsable?','Identificar competencias, límites de la decisión administrativa y eventual jurisdicción civil.','Declarar por acto administrativo cualquier dominio controvertido.','Ignorar procesos judiciales en todos los supuestos.','Crear una hipoteca por silencio.','La competencia administrativa no sustituye ilimitadamente la jurisdicción judicial.','TUO de la Ley 27444; Código Civil');


// Preguntas extra de arena inicial: diez por categoría, cincuenta en esta arena.
add('civil',0,'¿Qué significa que la inscripción de una compraventa ordinaria sea usualmente declarativa?','Publica un derecho cuya adquisición puede haberse producido antes.','Constituye necesariamente la propiedad solo al inscribir.','Hace irrelevante la validez del contrato.','Impide toda controversia entre terceros.','En la transferencia inmobiliaria ordinaria el acuerdo válido puede transmitir propiedad antes de la inscripción.','Código Civil, art. 949');
add('civil',0,'¿Qué derecho permite usar y disfrutar de un bien ajeno sin volverse dueño por ese solo hecho?','Usufructo.','Dominio pleno necesariamente.','Hipoteca bancaria.','Calificación registral.','El usufructo concede facultades de disfrute dentro de su régimen, sin transferir el dominio.','Código Civil, usufructo');
add('civil',0,'Un inmueble tiene varios titulares por cuotas ideales. ¿Qué institución describe esa situación?','Copropiedad.','Arrendamiento.','Prescripción extintiva.','Falsedad material.','La copropiedad admite varios titulares del mismo bien mediante cuotas ideales.','Código Civil, copropiedad');
add('civil',0,'Una persona ocupa un inmueble, pero no tiene título de propiedad. ¿Qué afirmación es posible?','Puede ejercer posesión sin ser propietaria.','Siempre adquiere dominio inmediatamente.','Toda posesión se registra como hipoteca.','La posesión no tiene ninguna consecuencia civil.','Posesión y propiedad no son equivalentes.','Código Civil, posesión');
add('civil',0,'Una persona concede a otra el uso temporal de un inmueble a cambio de renta. ¿Qué contrato describe mejor el caso?','Arrendamiento.','Donación de dominio.','Hipoteca sin registro.','Partición hereditaria.','El arrendamiento puede atribuir uso temporal a cambio de renta conforme al contrato.','Código Civil, arrendamiento');
add('registral',0,'¿Qué principio hace posible que un tercero conozca información contenida en los registros?','Publicidad registral.','Secreto general de toda partida.','Irretroactividad penal.','Confesión judicial.','La publicidad es función esencial del sistema registral.','Reglamento General de los Registros Públicos');
add('registral',0,'¿Qué asiento resulta relevante para determinar el orden de presentación de títulos?','El asiento de presentación en el Diario registral.','La boleta de mercado del vendedor.','El plano municipal por sí solo.','La fecha de compra del computador del notario.','La fecha y hora de presentación condicionan la prioridad registral.','RGRP, principio de prioridad preferente');
add('registral',0,'¿Cómo se llama la primera inscripción de dominio de un predio?','Inmatriculación.','Inscripción de embargo necesariamente.','Anulación de escritura.','Legalización de firmas.','La inmatriculación permite abrir por primera vez la partida del predio.','Código Civil, art. 2018');
add('registral',0,'¿Qué órgano actúa como segunda instancia del procedimiento registral?','El Tribunal Registral.','La SUNAT.','La Fiscalía de turno.','Un banco privado.','El Tribunal Registral revisa decisiones en apelación dentro del procedimiento registral.','Reglamento General de los Registros Públicos');
add('registral',0,'¿Puede la inscripción de un acto nulo sanearlo automáticamente?','No; inscripción y validez del acto son cuestiones diferentes.','Sí, siempre.','Sí, si se paga la tasa registral.','Sí, si el inmueble tiene posesión física.','El principio de legitimación no convalida actos nulos o anulables.','Código Civil, art. 2013');
add('penal',0,'¿Qué institución exige un análisis de responsabilidad más allá del mero resultado dañoso?','Culpabilidad penal.','Prioridad excluyente.','Separación de predios.','Otorgamiento de parte notarial.','La imputación penal requiere examinar elementos del hecho y responsabilidad personal.','Código Penal, parte general');
add('penal',0,'Una persona es acusada pero no existe sentencia de condena. ¿Cuál es la situación correcta?','La acusación no equivale por sí sola a culpabilidad demostrada.','La sola denuncia equivale a condena.','El acusado pierde automáticamente su propiedad.','No se requiere prueba ni defensa.','La presunción de inocencia opera durante el procedimiento.','Constitución Política del Perú');
add('penal',0,'Un sujeto adultera físicamente una firma en documento. ¿Qué tipo de asunto puede existir?','Una posible falsificación documental.','Una inmatriculación automática.','Una hipoteca legal inmediata.','Una cesión de posesión consensual.','La adulteración material de documentos puede integrar ilícitos contra la fe pública.','Código Penal, delitos de falsedad');
add('penal',0,'En un proceso, ¿qué principio permite al imputado defenderse y cuestionar pruebas?','Debido proceso y derecho de defensa.','Prioridad hipotecaria.','Publicidad notarial ilimitada.','Prescripción adquisitiva automática.','El debido proceso garantiza mecanismos de defensa y contradicción.','Constitución Política del Perú');
add('penal',0,'Una persona actúa sin intención pero infringiendo el deber de cuidado, en un supuesto tipificado. ¿Qué modalidad puede investigarse?','Conducta culposa.','Simulación absoluta civil necesariamente.','Tracto registral.','Subrogación del arrendamiento.','La culpa se analiza según el deber objetivo de cuidado y el tipo penal aplicable.','Código Penal, parte general');
add('notarial',0,'¿Qué significa que un instrumento sea protocolar?','Que se integra al protocolo notarial correspondiente.','Que se publica automáticamente en todas las partidas.','Que es siempre un acto penal.','Que pertenece al registro de vehículos de SUNARP.','La característica protocolar se relaciona con la conservación en registros notariales.','Decreto Legislativo 1049');
add('notarial',0,'Una persona firma un contrato ante notario y este legaliza la firma. ¿Qué certifica centralmente esa diligencia?','La firma en los términos de la certificación notarial.','La ausencia definitiva de cualquier nulidad contractual.','La propiedad de todos los bienes mencionados.','La creación de una hipoteca.','Certificar firmas no equivale a autorizar una escritura pública.','Decreto Legislativo 1049');
add('notarial',0,'¿Qué debe revisarse si alguien firma como apoderado de otra persona?','El alcance de las facultades que se le otorgaron.','Solo su lugar de nacimiento.','Que posea un inmueble de valor equivalente.','La fecha de un recibo bancario ajeno.','La representación exige facultades suficientes para el negocio.','Código Civil, representación');
add('notarial',0,'¿Cuál es una diferencia entre matriz y parte notarial?','La matriz permanece en protocolo; el parte es un traslado autorizado.','El parte siempre se firma por el comprador.','La matriz es una sentencia penal.','Ambos son contratos distintos por definición.','La legislación notarial regula traslados de instrumentos protocolares.','Decreto Legislativo 1049');
add('notarial',0,'El notario verifica identidad de comparecientes. ¿Qué propósito persigue?','Fortalecer autenticidad y seguridad en el otorgamiento de instrumentos.','Declarar propietario a cualquiera sin título.','Eliminar automáticamente todo litigio.','Sustituir el proceso judicial de sucesión.','La función notarial tiene deberes de identificación y fe documental.','Decreto Legislativo 1049');
add('administrativo',0,'¿Qué debe respetar una autoridad cuando resuelve una solicitud?','La competencia y el debido procedimiento.','Solo la preferencia verbal del solicitante.','La fecha del último partido deportivo.','La firma de un vecino ajeno como regla única.','Las actuaciones administrativas se sujetan a competencia y garantías.','TUO de la Ley 27444');
add('administrativo',0,'¿Qué significa que una resolución esté motivada?','Que expresa las razones fácticas y jurídicas pertinentes de la decisión.','Que contiene muchas páginas necesariamente.','Que siempre está a favor del administrado.','Que carece de fundamento jurídico.','La motivación conecta hechos, normas y conclusión.','TUO de la Ley 27444');
add('administrativo',0,'¿Es lo mismo una solicitud administrativa que una demanda judicial?','No, son actuaciones ante autoridades y procedimientos distintos.','Sí, siempre.','Solo se distinguen por el tipo de papel.','Toda solicitud inicia automáticamente un proceso penal.','Las competencias y cauces de la Administración difieren de la jurisdicción judicial.','TUO de la Ley 27444');
add('administrativo',0,'¿Cuál es un objetivo de los recursos administrativos?','Permitir cuestionar actos administrativos según los requisitos legales.','Crear propiedades por contrato privado.','Convertir una deuda civil en delito.','Sustituir la escritura pública de donación.','Los medios impugnatorios son mecanismos de revisión administrativa.','TUO de la Ley 27444');
add('administrativo',0,'Si una entidad emite una resolución fuera de sus atribuciones, ¿qué concepto es pertinente?','Vicio de competencia.','Tracto sucesivo.','Usufructo.','Testamento cerrado.','La competencia es requisito de validez del acto administrativo.','TUO de la Ley 27444');


// v14: 50 situaciones adicionales, diez por rama y distribuidas entre arenas 2 a 6.

add("civil",1,"Una persona ofrece vender un inmueble que aún no ha individualizado. ¿Qué aspecto jurídico debe aclararse primero?","La determinación o determinabilidad del bien y el objeto del contrato.","La fecha de la próxima elección municipal.","El nombre del registrador en turno.","La cantidad de muebles del vendedor.","Sin definir adecuadamente el objeto del negocio, no puede analizarse con rigor qué prestación se asumió.","Código Civil: acto jurídico y compraventa");
add("civil",1,"Una persona posee una vivienda alquilada y afirma ser dueña por vivir allí. ¿Qué diferencia es esencial?","El arrendatario puede poseer sin adquirir por ello el dominio.","Toda posesión es propiedad inmediata.","El contrato de alquiler constituye una hipoteca.","El arrendador pierde el dominio al entregar las llaves.","La posesión derivada del arrendamiento no se confunde con el derecho real de propiedad.","Código Civil: posesión y arrendamiento");
add("civil",2,"El comprador de un lote descubre una servidumbre existente. ¿Qué investigación es razonable?","Revisar título, alcance, titularidad y publicidad de la servidumbre.","Suponer que toda servidumbre termina con la venta.","Asumir que servidumbre e hipoteca son idénticas.","Prescindir del estado jurídico del predio.","La venta no elimina automáticamente las cargas o derechos reales preexistentes; se evalúa su régimen y oponibilidad.","Código Civil: servidumbres y derechos reales");
add("civil",2,"Se paga parcialmente una deuda documentada. ¿Qué debe distinguir el acreedor?","La cuantía pendiente y los efectos de la imputación de ese pago.","Que el pago parcial siempre elimina todo saldo.","Que la deuda se transforma en delito.","Que se constituye hipoteca sin inscripción.","El cumplimiento parcial no equivale necesariamente a la extinción total de la obligación.","Código Civil: cumplimiento de obligaciones");
add("civil",3,"Dos personas celebran contrato sometido a condición resolutoria. ¿Qué cuestión hay que estudiar?","Los efectos del acontecimiento previsto sobre la eficacia del acto.","La creación inevitable de propiedad registral.","La nulidad automática de toda condición.","La extinción de la personalidad de las partes.","La condición resolutoria se estudia según el acontecimiento pactado y los efectos legales asociados.","Código Civil: modalidades del acto jurídico");
add("civil",3,"Un tercero paga una obligación ajena y pretende reclamar al deudor. ¿Qué debe comprobar?","Si existe un supuesto legal o convencional de subrogación o reembolso.","Que cualquier pago le vuelve dueño de la casa.","Que todo pago obliga a inscribir una hipoteca.","Que el deudor incurrió necesariamente en delito.","El pago por tercero y el posible reembolso requieren analizar la relación jurídica y sus presupuestos.","Código Civil: pago y subrogación");
add("civil",4,"Una venta se celebra por representante con poder insuficiente. ¿Qué enfoque técnico corresponde?","Examinar las facultades, la eventual ratificación y la eficacia respecto del representado.","Afirmar que la firma del apoderado siempre obliga al dueño.","Suponer que todo poder incluye venta de inmuebles.","Reemplazar la revisión por el valor declarado.","La actuación representativa exige facultades suficientes y un análisis de los efectos de su exceso.","Código Civil: representación");
add("civil",4,"Una obligación tiene varios codeudores. ¿Qué diferencia debe revisar el abogado?","Si existe solidaridad o una obligación mancomunada según la fuente aplicable.","Que siempre existe solidaridad por haber varios deudores.","Que todo deudor comparte necesariamente una hipoteca.","Que todos tienen derechos idénticos sobre el bien.","La concurrencia de deudores no permite presumir sin más la solidaridad; importa el régimen de la obligación.","Código Civil: obligaciones con pluralidad de sujetos");
add("civil",5,"Una persona reclama nulidad contractual e invoca simultáneamente resolución por incumplimiento. ¿Qué debe ordenar primero?","Los presupuestos, efectos y compatibilidad de cada pretensión.","Que nulidad y resolución tienen los mismos requisitos.","Que el registro decide siempre la causa de nulidad.","Que un incumplimiento prueba simulación absoluta.","Nulidad y resolución responden a supuestos diferentes y deben argumentarse separadamente.","Código Civil: invalidez y resolución contractual");
add("civil",5,"Una demanda de reivindicación se enfrenta a una posesión alegada como prescriptiva. ¿Qué exige el análisis profesional?","Individualizar el bien, títulos y prueba de todos los requisitos de prescripción.","Tomar únicamente el número de recibos de servicio.","Declarar propietario al poseedor sin más hechos.","Decidir por la antigüedad de la pintura de la casa.","La titularidad dominical y la posible adquisición originaria se contrastan con prueba y requisitos legales concretos.","Código Civil: propiedad, reivindicación y prescripción");
add("registral",1,"¿Qué identifica el número de una partida registral?","El historial organizado del bien o sujeto en el registro correspondiente.","La solvencia financiera de su titular.","El valor comercial exacto e invariable del predio.","La existencia de una sentencia penal.","La partida reúne asientos del registro; no reemplaza una tasación ni acredita hechos ajenos al sistema.","Reglamento General de los Registros Públicos");
add("registral",1,"Un asiento registral publicita una hipoteca. ¿Para qué sirve su publicidad?","Para conocer la existencia y rango registral del gravamen conforme al sistema.","Para acreditar que la deuda jamás se pagará.","Para otorgar propiedad al banco de inmediato.","Para convertir el préstamo en escritura de venta.","La publicidad permite conocer el gravamen y evaluar su oponibilidad y prioridad.","Código Civil: hipoteca y publicidad registral");
add("registral",2,"Un título se presenta primero, pero contiene defecto subsanable. ¿Qué debe examinarse?","La vigencia del asiento de presentación y su subsanación dentro del procedimiento.","Solo el día de cumpleaños del adquirente.","Que todo defecto crea nulidad penal.","Que los títulos posteriores siempre ganan rango.","La prioridad y la posibilidad de subsanar dependen del asiento, sus plazos y las reglas de calificación.","Reglamento General de los Registros Públicos");
add("registral",2,"Un registrador advierte discrepancia entre el título y la partida. ¿Cuál es su tarea?","Evaluar el obstáculo conforme a las reglas de calificación registral.","Modificar libremente las declaraciones de las partes.","Resolver un juicio de reivindicación sin proceso.","Inscribir ignorando la discrepancia.","El registrador contrasta título y antecedentes relevantes dentro de los límites de su competencia.","RGRP: legalidad y calificación");
add("registral",3,"Una persona pretende inscribir segunda transferencia cuando falta el título intermedio. ¿Qué principio resulta decisivo?","Tracto sucesivo y continuidad de titularidades inscritas.","Legalidad penal del comprador.","Silencio administrativo positivo automático.","Imputación de pagos de préstamo.","La cadena de derechos debe conservar continuidad salvo excepción normativa.","Código Civil, art. 2015");
add("registral",3,"Un tercero compra confiando solo en el nombre del titular inscrito. ¿Qué comprobación falta?","Revisar además asientos y títulos archivados pertinentes para la fe pública.","La marca del vehículo del vendedor.","El número de visitas al portal de SUNARP.","Que el vendedor haya estudiado Derecho.","La protección registral del tercero no depende solo de mirar un nombre; exige condiciones legales.","Código Civil, art. 2014");
add("registral",4,"Se solicitan dos inscripciones sobre un predio cuya identificación técnica no coincide. ¿Qué cuestión debe resolverse?","La identidad del predio y los obstáculos técnicos o registrales detectados.","La inscripción conjunta sin examinar planos.","Que la diferencia de área siempre es irrelevante.","Que todo plano privado sana el registro.","La especialidad exige identificar el inmueble y evaluar discrepancias conforme al procedimiento correspondiente.","RGRP y Reglamento del Registro de Predios");
add("registral",4,"Dos hipotecas compatibles llegan al Registro en momentos distintos. ¿Qué determina normalmente su rango?","Las reglas de prioridad registral y la presentación del título.","Solo la fecha de impresión de los contratos.","El banco de mayor tamaño.","La cantidad de páginas del instrumento.","Entre derechos compatibles, la prioridad de rango se evalúa registralmente y no por intuición comercial.","Código Civil, art. 2016");
add("registral",5,"Un conflicto de doble venta involucra inscripción y alegaciones de mala fe. ¿Qué método jurídico es adecuado?","Distinguir adquisición civil, prioridad, requisitos de protección y prueba de mala fe.","Suponer que cualquier primera inscripción gana sin excepciones.","Declarar nulos todos los contratos de doble venta automáticamente.","Decidir únicamente quién pagó más dinero.","Los conflictos de doble disposición requieren articular normas civiles y registrales, no aplicar una sola regla de manera aislada.","Código Civil, arts. 949, 1135 y 2014");
add("registral",5,"Se intenta rectificar un asiento de predio afectando derechos posteriores. ¿Qué debe analizarse?","Vía de rectificación, sustento documental y protección de titulares involucrados.","Borrar sin trámite las inscripciones contradictorias.","Que toda rectificación tiene el mismo procedimiento.","Que la solicitud verbal basta en todos los casos.","La rectificación registral está sujeta a causales, documentos y límites que salvaguardan la seguridad jurídica.","Reglamento General de los Registros Públicos");
add("penal",1,"Una persona incumple un contrato pero no se acredita engaño inicial. ¿Cuál es la cautela?","No calificar automáticamente el incumplimiento como estafa.","Asumir que toda deuda es delito.","Imponer condena sin prueba.","Sustituir el juicio por una observación registral.","La estafa requiere elementos típicos propios distintos del mero incumplimiento contractual.","Código Penal: delitos patrimoniales");
add("penal",1,"En un proceso penal se acusa a alguien sin sentencia. ¿Cuál es la regla de trato?","Presunción de inocencia mientras no exista condena en los términos legales.","La acusación equivale a condena.","La noticia periodística prueba responsabilidad.","El acusado pierde toda defensa.","La presunción de inocencia es una garantía constitucional y procesal.","Constitución Política del Perú: garantías penales");
add("penal",2,"Alguien altera la fecha de una escritura para simular antigüedad. ¿Qué aspecto es central?","Examinar falsedad material y demás elementos del tipo concreto.","Presumir que el documento queda convalidado.","Tratarlo únicamente como error de digitación.","Afirmar que siempre constituye falsedad ideológica.","Modificar materialmente un instrumento plantea problemas diferentes a insertar contenido mendaz en documento auténtico.","Código Penal: fe pública");
add("penal",2,"Una conducta causa daño por descuido. ¿Qué debe verificarse antes de imputar delito culposo?","Que exista tipo culposo aplicable, deber de cuidado y conexión con el resultado.","Que cualquier daño se sancione penalmente.","Que se inscriba una hipoteca.","Que el perjudicado firme una escritura.","La responsabilidad culposa exige presupuestos típicos y normativos propios.","Código Penal: culpabilidad y culpa");
add("penal",3,"Dos personas realizan una conducta aparentemente típica en legítima defensa alegada. ¿Qué corresponde?","Examinar los presupuestos de la causa de justificación conforme a hechos y ley.","Condenar sin examinar la defensa.","Considerar irrelevante la proporcionalidad y necesidad.","Concluir que todo acto violento está justificado.","La tipicidad aparente no basta para condenar si concurre una causa de justificación legal.","Código Penal: causas de justificación");
add("penal",3,"Un documento falso se usa para inscribir un acto. ¿Qué distinción hace falta?","Separar posibles delitos documentales del efecto civil y del procedimiento registral.","Concluir que registro y justicia penal son lo mismo.","Sustituir la investigación por la mera sospecha.","Presumir válida la transferencia por recibir el documento.","Las consecuencias penales, civiles y registrales tienen objetos y autoridades diferentes.","Código Penal: fe pública; normativa civil y registral");
add("penal",4,"El fiscal atribuye intervención a una persona sin precisar su aporte. ¿Qué exige el análisis?","Distinguir autoría, participación y elementos de imputación individual.","Declarar autor a todo conocido del investigado.","Equiparar presencia física y autoría.","Suponer que toda cooperación es irrelevante.","La responsabilidad penal es personal y exige justificar la contribución jurídicamente relevante.","Código Penal: autoría y participación");
add("penal",4,"Un acusado presenta duda razonable sobre elemento esencial del delito. ¿Qué principio importa?","El estándar probatorio y la presunción de inocencia.","La calificación registral como sustituto de prueba.","La obligación de autoincriminarse.","Que una denuncia sea prueba concluyente.","La condena exige suficiencia probatoria conforme a garantías procesales.","Constitución y Código Procesal Penal");
add("penal",5,"Se cuestiona una imputación por falsedad ideológica basada solo en declaraciones inexactas. ¿Qué exige el examen?","Determinar documento, deber de veracidad, conducta típica, dolo y relevancia jurídica.","Suponer que toda inexactitud verbal es delito.","Confundir necesariamente falsedad ideológica y material.","Ignorar el contenido del instrumento.","La tipicidad de la falsedad ideológica depende de elementos concretos y del instrumento de que se trate.","Código Penal: falsedad ideológica");
add("penal",5,"En un caso complejo hay responsabilidad civil y penal derivada de un mismo hecho. ¿Qué enfoque corresponde?","Examinar separadamente presupuestos, prueba, consecuencias y vías de tutela.","Considerar idénticos los criterios de ambas responsabilidades.","Asumir que una deuda contractual define la culpabilidad penal.","Suponer que la inscripción registral absuelve penalmente.","Un mismo contexto fáctico puede dar lugar a regímenes jurídicos distintos sin que sus requisitos se sustituyan.","Código Civil y Código Penal");
add("notarial",1,"Una persona confunde copia simple con testimonio notarial. ¿Qué diferencia debe conocer?","El testimonio tiene régimen de traslado autorizado del instrumento protocolar.","Toda copia simple produce idéntica autenticidad.","El testimonio es necesariamente sentencia judicial.","El protocolo es un archivo bancario.","Los traslados notariales se regulan formalmente y no equivalen a fotocopias comunes.","Decreto Legislativo 1049");
add("notarial",1,"El notario certifica una firma en contrato privado. ¿Qué NO debe inferirse de esa diligencia?","Que el notario haya validado todo el contenido sustantivo del contrato.","Que existe actuación notarial sobre firma.","Que una certificación tiene requisitos.","Que debe identificarse el firmante conforme a ley.","La certificación de firma no convierte el documento privado en escritura pública ni sanea sus defectos.","Decreto Legislativo 1049");
add("notarial",2,"Una persona quiere donar un inmueble solo con firmas legalizadas. ¿Qué debe advertir el asesor?","La donación inmobiliaria requiere escritura pública con formalidad solemne.","Que basta una llamada telefónica.","Que una firma legalizada sustituye toda solemnidad.","Que inscripción y escritura son términos idénticos.","La ley civil exige forma pública bajo sanción de nulidad para donaciones inmobiliarias.","Código Civil, art. 1625");
add("notarial",2,"Un poder permite administrar pero no expresa disposición. ¿Qué debe hacer el notario ante una venta?","Comprobar que las facultades alcanzan el acto de disposición pretendido.","Presumir que toda administración autoriza enajenar.","Eliminar el poder del instrumento.","Sustituir al representado sin consentimiento.","Las facultades representativas se valoran por su alcance y por la naturaleza del acto.","Código Civil: representación; Decreto Legislativo 1049");
add("notarial",3,"Se requiere incorporar una corrección al instrumento protocolar ya autorizado. ¿Qué estudio procede?","El mecanismo notarial legalmente permitido y sus límites.","Modificar libremente la matriz sin formalidades.","Destruir todos los traslados anteriores.","Usar un correo informal como única rectificación.","El protocolo se conserva y las correcciones tienen formas y controles jurídicos propios.","Decreto Legislativo 1049: instrumentos protocolares");
add("notarial",3,"El otorgante actúa a través de apoderado extranjero. ¿Qué revisión es relevante?","Validez formal, legalización o apostilla cuando corresponda y alcance de facultades.","Aceptar cualquier fotocopia sin autenticación.","Suponer que nunca se admiten poderes extranjeros.","Exigir automáticamente una sentencia peruana.","La circulación de instrumentos extranjeros exige examinar autenticidad y efectos según su régimen aplicable.","Decreto Legislativo 1049; representación e instrumentos extranjeros");
add("notarial",4,"Se solicita un parte para inscribir un acto en SUNARP. ¿Qué debe distinguir el profesional?","Contenido de la matriz, autenticidad del traslado y requisitos del Registro.","Que cualquier imagen del documento es idéntico parte.","Que el asiento registral reemplaza al instrumento otorgado.","Que se puede omitir verificar a los otorgantes.","El traslado y su presentación registral son pasos distintos sometidos a reglas formales.","Ley del Notariado y normativa registral");
add("notarial",4,"El notario constata identidad, pero surgen indicios de suplantación. ¿Qué debe valorar?","Diligencias de identificación aplicables, evidencias y deberes de prevención.","Firmar sin comprobaciones ante cualquier indicio.","Concluir que una firma basta para toda identidad.","Resolver mediante asiento de hipoteca.","La función notarial comprende deberes de verificación y seguridad de los instrumentos.","Decreto Legislativo 1049");
add("notarial",5,"Una escritura documenta acto formalmente correcto pero con objeto ilícito. ¿Qué conclusión técnica es válida?","La forma pública no sana una causa sustantiva de invalidez del negocio.","La intervención notarial elimina cualquier nulidad.","El instrumento obliga siempre al juez a convalidar.","Toda nulidad se convierte en defecto de firma.","Autenticidad instrumental y validez sustantiva del acto son planos jurídicos distintos.","Código Civil: acto jurídico; Decreto Legislativo 1049");
add("notarial",5,"Se discute la eficacia de un poder revocado cuyo uso antecede o sigue a su publicidad. ¿Qué exige el análisis?","Verificar la cronología, facultades, conocimiento y reglas de oponibilidad aplicables.","Resolver solo por la firma más elegante.","Suponer que la revocación nunca produce efectos.","Ignorar la existencia de terceros.","Los efectos de la representación y revocación requieren análisis temporal y de protección de terceros.","Código Civil: representación; normas registrales");
add("administrativo",1,"Una entidad recibe solicitud y debe contestar. ¿Qué premisa corresponde?","Actuar conforme a competencia, plazo y procedimiento aplicable.","Responder según preferencia del funcionario sin norma.","Suponer que todo pedido se aprueba automáticamente.","Delegar toda resolución a un notario.","La actividad administrativa está sujeta a competencia y debido procedimiento.","Ley 27444: procedimiento administrativo");
add("administrativo",1,"Una resolución incluye solo el texto «no procede». ¿Qué cuestión surge?","Posible insuficiencia de motivación al no justificar los hechos y normas relevantes.","Que la decisión siempre es correcta.","Que los actos no requieren fundamentación.","Que existe una hipoteca tácita.","La motivación exige explicar razonablemente las razones de la decisión administrativa.","TUO de la Ley 27444");
add("administrativo",2,"Una entidad notifica un acto después de emitirlo. ¿Qué distinción debe realizarse?","La validez del acto y su eficacia vinculada a la notificación.","Suponer que notificar crea por sí solo competencia.","Equiparar notificación con inscripción inmobiliaria.","Declarar que toda notificación tiene efectos retroactivos.","Validez y eficacia administrativa son planos jurídicos distintos.","TUO de la Ley 27444: eficacia y notificación");
add("administrativo",2,"Una persona interpone recurso ante una entidad. ¿Qué verifica primero un asesor?","Procedencia, plazo, órgano y requisitos del recurso específico.","Que todos los recursos se dirigen al mismo juez penal.","Que todos los plazos son indefinidos.","Que cualquier comentario de red social equivale a recurso.","La revisión administrativa se somete a exigencias de admisibilidad y competencia.","TUO de la Ley 27444: recursos");
add("administrativo",3,"Un procedimiento invoca silencio administrativo positivo sin comprobar supuestos. ¿Qué corresponde?","Examinar el régimen vigente del procedimiento y sus exclusiones legales.","Suponer que todo silencio es positivo.","Afirmar que el silencio siempre equivale a condena.","Sustituir la verificación por copia de una solicitud.","El efecto jurídico del silencio depende de la normativa del procedimiento y sus excepciones.","TUO de la Ley 27444; normas especiales");
add("administrativo",3,"Una autoridad fundamenta sanción en infracción no tipificada para ese supuesto. ¿Qué garantía se compromete?","Principio de tipicidad administrativa sancionadora.","Prescripción adquisitiva inmobiliaria.","Usufructo voluntario.","Sucesión testamentaria.","La potestad sancionadora requiere conducta prevista dentro del marco normativo aplicable.","TUO de la Ley 27444: potestad sancionadora");
add("administrativo",4,"Una entidad impone multa sin valorar criterios legalmente aplicables de proporcionalidad. ¿Qué se cuestiona?","La razonabilidad de la medida sancionadora.","La fecha de escritura privada.","La falta de tracto sucesivo civil.","La existencia automática de delito.","La elección y graduación de sanciones están sujetas a límites y criterios de razonabilidad.","TUO de la Ley 27444: razonabilidad");
add("administrativo",4,"Se confirma en apelación un acto sin contestar agravios decisivos. ¿Qué problema jurídico aparece?","La motivación suficiente de la resolución del recurso.","La nulidad de toda escritura notarial.","La inscripción de oficio de propiedad.","La imposibilidad de revisar actos administrativos.","La instancia revisora debe justificar su decisión según el procedimiento y alegaciones pertinentes.","TUO de la Ley 27444: motivación y recursos");
add("administrativo",5,"Un acto administrativo favorable es revisado de oficio después de consolidar efectos. ¿Qué debe estudiarse?","Competencia, causal, plazos, garantías y consecuencias para terceros.","La libertad absoluta de revocar sin trámite.","El valor de mercado como único requisito.","Que ningún acto favorable puede revisarse jamás.","La revisión de oficio está sometida a requisitos y límites sustantivos y procedimentales.","TUO de la Ley 27444: revisión de oficio");
add("administrativo",5,"Hay procedimiento registral especial y una norma administrativa general. ¿Qué enfoque aplica un profesional?","Armonizar especialidad del procedimiento y garantías legales correspondientes.","Aplicar indiscriminadamente un solo plazo a todos los trámites.","Tratar la calificación registral como sentencia penal.","Desconocer los órganos registrales especializados.","La especialidad no suprime el deber de identificar las reglas y garantías pertinentes.","TUO de la Ley 27444 y normativa registral");

export const QUESTIONS: Question[] = Q;
export function availableQuestions(cat: CategoryId, arena: number) { return QUESTIONS.filter(q => q.category===cat && q.arena===arena); }
export function pickQuiz(cat: CategoryId, arena: number, recentIds: string[] = []): {questions:Question[]; review:boolean} {
  const pool = availableQuestions(cat,arena);
  // Si el banco de esta arena aún es pequeño, completar con preguntas de repaso anteriores sin ocultarlo.
  const review = pool.length < 5;
  const extra = review ? QUESTIONS.filter(q => q.category===cat && q.arena<arena) : [];
  const prioritized = [...pool.filter(q=>!recentIds.includes(q.id)), ...pool.filter(q=>recentIds.includes(q.id))];
  const mixed = [...prioritized, ...extra.filter(q=>!recentIds.includes(q.id)), ...extra.filter(q=>recentIds.includes(q.id))];
  const selected:Question[]=[];
  for(const q of mixed) if(!selected.some(s=>s.id===q.id)) selected.push(q);
  if(selected.length<5) return {questions:selected,review};
  // Las cinco preguntas se barajan, priorizando las que no se hayan visto recientemente.
  const chosen = selected.slice(0,5);
  for(let i=chosen.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1)); [chosen[i],chosen[j]]=[chosen[j],chosen[i]];}
  return {questions:chosen, review};
}
